'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dnanasum = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dnanasum.main, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 3', function test( t ) {
	t.strictEqual( dnanasum.main.length, 3, 'returns expected value' );
	t.end();
});

tape( 'the function calculates the sum of absolute values (ignoring NaN values)', function test( t ) {
	var sum;
	var x;

	x = new Float64Array( [ 1.0, -2.0, -4.0, 5.0, 0.0, NaN, 3.0, 0.0, -3.0, 3.0, NaN ] ); // eslint-disable-line max-len
	sum = dnanasum.main( x.length, x, 1 );
	t.strictEqual( sum, 21.0, 'returns expected value' );

	x = new Float64Array( [ 1.0, -2.0, -4.0, NaN, 5.0, 0.0, 3.0, NaN ] );
	sum = dnanasum.main( x.length, x, 1 );
	t.strictEqual( sum, 15.0, 'returns expected value' );

	x = new Float64Array( [ -4.0, NaN, -4.0 ] );
	sum = dnanasum.main( x.length, x, 1 );
	t.strictEqual( sum, 8.0, 'returns expected value' );

	x = new Float64Array( [ NaN, 4.0 ] );
	sum = dnanasum.main( x.length, x, 1 );
	t.strictEqual( sum, 4.0, 'returns expected value' );

	x = new Float64Array( [ NaN, NaN ] );
	sum = dnanasum.main( x.length, x, 1 );
	t.strictEqual( sum, 0.0, 'returns expected value' );

	x = new Float64Array( [ NaN ] );
	sum = dnanasum.main( x.length, x, 1 );
	t.strictEqual( sum, 0.0, 'returns expected value' );

	x = new Float64Array( [ 4.0 ] );
	sum = dnanasum.main( x.length, x, 1 );
	t.strictEqual( sum, 4.0, 'returns expected value' );

	x = new Float64Array( [ 1.0, 1.0e100, 1.0, -1.0e100 ] );
	sum = dnanasum.main( x.length, x, 1 );
	t.strictEqual( sum, 2.0e100, 'returns expected value' );

	t.end();
});

tape( 'if provided an `N` parameter less than or equal to `0`, the function returns `0.0`', function test( t ) {
	var sum;
	var x;

	x = new Float64Array( [ 1.0, -2.0, -4.0, 5.0, 3.0 ] );

	sum = dnanasum.main( 0, x, 1 );
	t.strictEqual( sum, 0.0, 'returns expected value' );

	sum = dnanasum.main( -1, x, 1 );
	t.strictEqual( sum, 0.0, 'returns expected value' );

	t.end();
});

tape( 'if provided an `N` parameter equal to `1`, the function returns the first element', function test( t ) {
	var sum;
	var x;

	x = new Float64Array( [ 1.0, -2.0, -4.0, 5.0, 3.0 ] );

	sum = dnanasum.main( 1, x, 1 );
	t.strictEqual( sum, 1.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports a `stride` parameter', function test( t ) {
	var sum;
	var x;

	x = new Float64Array([
		1.0,  // 0
		2.0,
		2.0,  // 1
		-7.0,
		-2.0, // 2
		3.0,
		4.0,  // 3
		2.0,
		NaN,  // 4
		NaN
	]);
	sum = dnanasum.main( 5, x, 2 );

	t.strictEqual( sum, 9.0, 'returns expected value' );
	t.end();
});

tape( 'the function supports a negative `stride` parameter', function test( t ) {
	var sum;
	var x;

	x = new Float64Array([
		NaN,  // 4
		NaN,
		1.0,  // 3
		2.0,
		2.0,  // 2
		-7.0,
		-2.0, // 1
		3.0,
		4.0,  // 0
		2.0
	]);
	sum = dnanasum.main( 5, x, -2 );

	t.strictEqual( sum, 9.0, 'returns expected value' );
	t.end();
});

tape( 'if provided a `stride` parameter equal to `0`, the function returns the sum of the first element repeated N times', function test( t ) {
	var sum;
	var x;

	x = new Float64Array( [ 1.0, -2.0, -4.0, 5.0, 3.0 ] );

	sum = dnanasum.main( x.length, x, 0 );
	t.strictEqual( sum, 5.0, 'returns expected value' );

	t.end();
});

tape( 'if provided a `stride` parameter equal to `0` and the first element is `NaN`, the function returns `0.0`', function test( t ) {
	var sum;
	var x;

	x = new Float64Array( [ NaN, -2.0, -4.0, 5.0, 3.0 ] );

	sum = dnanasum.main( x.length, x, 0, 0 );
	t.strictEqual( sum, 0.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports view offsets', function test( t ) {
	var sum;
	var x0;
	var x1;

	x0 = new Float64Array([
		2.0,
		1.0,  // 0
		2.0,
		-2.0, // 1
		-2.0,
		2.0,  // 2
		3.0,
		4.0,  // 3
		6.0,
		NaN,  // 4
		NaN
	]);

	x1 = new Float64Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 ); // start at 2nd element

	sum = dnanasum.main( 5, x1, 2 );
	t.strictEqual( sum, 9.0, 'returns expected value' );

	t.end();
});
